// GENERATED by scripts/sync-core.mjs from js/core. Edit the original, then run `npm run sync`.
// The points ledger. Balances are never stored on their own: they are the
// sum of the ledger. Every transaction has two signed effects:
//
//   amount      change to the available balance (what can be spent)
//   held_delta  change to the held balance (reserved for a redemption)
//
//   type     amount  held_delta   when
//   earn       +n        0        gameplay, welcome, referral
//   reserve    -n       +n        a reward is reserved
//   release    +n       -n        a reservation is cancelled or expires
//   redeem      0       -n        the merchant validates the code (points leave for good)
//   refund     +n        0        an admin reverses a completed redemption
//   expire     -n        0        balance expiry after inactivity
//   adjust     ±n        0        admin adjustment (with a reason)
//
// Invariants: available >= 0 and held >= 0 after every transaction, and each
// idempotency key is used once.

export const TX_TYPES = ['earn', 'reserve', 'release', 'redeem', 'refund', 'expire', 'adjust'];

export class LedgerError extends Error {
  constructor(code, message = code) {
    super(message);
    this.code = code;
  }
}

/** Signed effects of a transaction of `points` (positive, except adjust which may be negative). */
export function effects(type, points) {
  if (!Number.isInteger(points)) throw new LedgerError('invalid_points');
  if (type === 'adjust') {
    if (points === 0) throw new LedgerError('invalid_points');
    return { amount: points, held_delta: 0 };
  }
  if (points <= 0) throw new LedgerError('invalid_points');
  switch (type) {
    case 'earn':
    case 'refund': return { amount: points, held_delta: 0 };
    case 'reserve': return { amount: -points, held_delta: points };
    case 'release': return { amount: points, held_delta: -points };
    case 'redeem': return { amount: 0, held_delta: -points };
    case 'expire': return { amount: -points, held_delta: 0 };
    default: throw new LedgerError('invalid_type');
  }
}

export function balances(txs) {
  let available = 0, held = 0, earned = 0, redeemed = 0;
  for (const t of txs) {
    available += t.amount;
    held += t.held_delta;
    if (t.type === 'earn' || (t.type === 'adjust' && t.amount > 0)) earned += t.amount;
    if (t.type === 'redeem') redeemed -= t.held_delta;
  }
  return { available, held, total: available + held, earned, redeemed };
}

/**
 * In-memory ledger with the same rules as the database. Used in preview mode
 * and in tests; the database enforces them with a row lock per wallet, a
 * unique idempotency key and CHECK constraints.
 */
export class MemoryLedger {
  constructor(transactions = [], { now = () => new Date(), id = () => crypto.randomUUID() } = {}) {
    this.transactions = transactions;
    this.now = now;
    this.id = id;
  }

  forUser(userId) {
    return this.transactions.filter((t) => t.user_id === userId);
  }

  balance(userId) {
    return balances(this.forUser(userId));
  }

  /**
   * Post a transaction. Returns {tx, duplicate}. Re-posting the same
   * idempotency key with the same user, type and points returns the original
   * transaction; with different values it throws idempotency_conflict.
   */
  post({ user_id, type, points, idempotency_key, reference_type = null, reference_id = null, funding_source = null, note = null, actor = 'system' }) {
    if (!user_id) throw new LedgerError('invalid_user');
    if (!TX_TYPES.includes(type)) throw new LedgerError('invalid_type');
    if (!idempotency_key) throw new LedgerError('idempotency_key_required');
    const existing = this.transactions.find((t) => t.idempotency_key === idempotency_key);
    if (existing) {
      if (existing.user_id !== user_id || existing.type !== type || existing.points !== points) {
        throw new LedgerError('idempotency_conflict');
      }
      return { tx: existing, duplicate: true };
    }
    const fx = effects(type, points);
    const bal = this.balance(user_id);
    if (bal.available + fx.amount < 0) throw new LedgerError('insufficient_points');
    if (bal.held + fx.held_delta < 0) throw new LedgerError('insufficient_held');
    const tx = {
      id: this.id(),
      user_id,
      type,
      points,
      amount: fx.amount,
      held_delta: fx.held_delta,
      status: 'posted',
      reference_type,
      reference_id,
      funding_source,
      note,
      actor,
      idempotency_key,
      created_at: this.now().toISOString()
    };
    this.transactions.push(tx);
    return { tx, duplicate: false };
  }
}
